 { json: { url: B + GLP + '/glossary-terms?limit=500', mode: MODE, STR, GL } },
 { json: { url: B + BRAIN + '/keys?limit=500&include_translations=1&filter_archived=exclude&filter_keys=' + encodeURIComponent(STR.map(s => s.k).join(',')) } }
