  if (q.kind === 'string') ok = ok && b.translation && b.translation.translation === q.want;
  out.push({ kind: q.kind, k: q.k || '', status: r.statusCode, ok, err: ok ? '' : JSON.stringify(b.error || b.errors || b).slice(0, 300), terms: (b.data || []).map(d => d.term + '#' + d.id).join(', ') }); }
return [{ json: { n: out.length, okN: out.filter(x => x.ok).length, out } }];
